function onEnterInSearchTerm() {
  // on enter
  // if not searching, start the search
  // if searching, stop and then start again
  if (
    gSearchStopButton.getAttribute("data-l10n-id") ==
    "ab-search-dialog-search-button"
  ) {
    onSearch();
  } else {
    onSearchStop();
    onSearch();
  }
}

